refused_program.body:
set -euo pipefail

upstream_ref="{upstream_remote}/{upstream_branch}"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

if ! git rev-parse -q --verify MERGE_HEAD >/dev/null 2>&1; then
  git merge --no-commit --no-ff "$upstream_ref" || true
  git rev-parse -q --verify MERGE_HEAD >/dev/null 2>&1 || {
    echo "merge could not be started" >&2
    exit 1
  }
fi

merge_head="$(git rev-parse MERGE_HEAD)"
base="$(git merge-base HEAD "$merge_head")"
git diff --name-only --diff-filter=U -z > "$tmp/conflicts"

while IFS= read -r -d '' path; do
  [ -n "$path" ] || continue

  if ! git cat-file -e "$merge_head:$path" 2>/dev/null; then
    git rm -q -f -- "$path" 2>/dev/null || true
    continue
  fi

  if ! git cat-file -e "HEAD:$path" 2>/dev/null; then
    git checkout --theirs -- "$path" 2>/dev/null || git checkout --theirs "$path"
    git add -- "$path"
    continue
  fi

  if [ "$(git diff --numstat "$base" HEAD -- "$path" | awk '$1=="-" && $2=="-" { print "yes"; exit }')" = yes ]; then
    git checkout --theirs -- "$path" 2>/dev/null || git checkout --theirs "$path"
    git add -- "$path"
    continue
  fi

  git show "$merge_head:$path" > "$tmp/up"
  git show "HEAD:$path" > "$tmp/local"

  git diff -U0 "$base" HEAD -- "$path" | awk '
    function flush() {
      if (open) {
        extra = addn - deln
        if (extra > 0) {
          for (i = addn - extra + 1; i <= addn; i++) {
            printf "%d\037%s\n", c + (i - 1), plus[i]
          }
        }
      }
      open = 0
    }
    /^@@/ {
      flush()
      match($0, /-[0-9]+(,[0-9]+)?/)
      old = substr($0, RSTART + 1, RLENGTH - 1)
      split(old, oa, ",")
      deln = (oa[2] == "") ? 1 : oa[2] + 0
      match($0, /\+[0-9]+(,[0-9]+)?/)
      new = substr($0, RSTART + 1, RLENGTH - 1)
      split(new, na, ",")
      c = na[1] + 0
      addn = 0
      open = 1
      next
    }
    /^\+\+\+/ { next }
    /^\+/ { addn++; plus[addn] = substr($0, 2); next }
    /^-/ { next }
    END { flush() }
  ' > "$tmp/added"

  awk -v upfile="$tmp/up" -v localfile="$tmp/local" -v addedfile="$tmp/added" '
    BEGIN {
      n = 0
      while ((getline line < upfile) > 0) { up[++n] = line }
      close(upfile)
      m = 0
      while ((getline line < localfile) > 0) { lo[++m] = line }
      close(localfile)
      while ((getline line < addedfile) > 0) {
        split(line, parts, "\037")
        add[parts[1] + 0] = parts[2]
      }
      close(addedfile)
      for (i = 1; i <= n; i++) {
        if (!(up[i] in upidx)) upidx[up[i]] = i
      }
      i = 1
      while (i <= m) {
        if (i in add) {
          start = i
          k = 0
          while (i <= m && (i in add)) {
            if (!(add[i] in upidx)) { k++; blk[k] = add[i] }
            i++
          }
          if (k > 0) {
            p = start - 1
            while (p >= 1 && !(lo[p] in upidx)) p--
            if (p >= 1) anchor = upidx[lo[p]]
            else anchor = 0
            for (j = 1; j <= k; j++) {
              insn[anchor]++
              ins[anchor, insn[anchor]] = blk[j]
            }
          }
        } else {
          i++
        }
      }
      for (j = 1; j <= insn[0]; j++) print ins[0, j]
      for (i = 1; i <= n; i++) {
        print up[i]
        for (j = 1; j <= insn[i]; j++) print ins[i, j]
      }
    }
  ' > "$tmp/merged"

  cp "$tmp/merged" "$path"
  git add -- "$path"
done < "$tmp/conflicts"

if git rev-parse -q --verify MERGE_HEAD >/dev/null 2>&1; then
  git -c user.name="git maintenance" -c user.email="maintenance@example.invalid" -c commit.gpgsign=false commit --no-edit
fi
